package postgresql

import (
	"encoding/base64"
	"strconv"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// The expected values were generated by PostgreSQL 17 itself:
//
//	SET password_encryption = 'scram-sha-256';
//	CREATE ROLE ... PASSWORD '<password>';
//	SELECT rolpassword FROM pg_authid;
//
// Hashing the same password with the same salt and iterations must give the
// same result, otherwise the role could not log in.
func TestScramSHA256Password(t *testing.T) {
	var tests = []struct {
		name     string
		password string
		expected string
	}{
		{
			name:     "ASCII",
			password: "pencil",
			expected: "SCRAM-SHA-256$4096:nBZw/pXHfglx9Uj38kTBaw==$kGNAwejTyDeIo7PF3ThjzBaKwu6Dw5If2OYxTD2AstI=:U/rTZUu3HZekCvxnzF65xDuso9CTdPudq8r2EvaCHao=",
		},
		{
			name:     "ASCII symbols",
			password: `p@ss w0rd'"$\`,
			expected: "SCRAM-SHA-256$4096:uK5ktiTcRCnYWCPlTu1lQA==$UziWBFTQaf9PZR6HLaS9IJhZDlmYt8rxarPPiW/I6eo=:12BJoKpcId74kQjCwnQMwwLkvlTx3bTzQY9zLr14JOg=",
		},
		{
			name:     "non default iterations",
			password: "pencil",
			expected: "SCRAM-SHA-256$10000:8ctmNn2eRjVnmCy9tDFnnA==$WTzMf8t3U+/P620JiLg6ym2geCl8jPxpBSEMqMAk1sk=:stXoeL1Fe/3uOOGc+JOtE85uGwN3A4STdslwL8+Tp4w=",
		},
		{
			name:     "non ASCII",
			password: "пароль",
			expected: "SCRAM-SHA-256$4096:j40Cwk6JkYzcp5c498nLog==$SN6J3quI0lXOMPHUBSGbZk6pMZiboDkSYMt1dm2edPk=:gNlf+yXocYpqd+bIDI4Vd2syhb/XkW2XkXi1VswkT/Y=",
		},
		{
			name:     "SASLprep removes the soft hyphen",
			password: "pen\u00ADcil",
			expected: "SCRAM-SHA-256$4096:geQLO9Lb9HXwgrRIDTcDsg==$UcFsMtBD5/kIg/J94obHyTjbO93OIYvi/HCJ5xewcyM=:4fpSn48KtAfy82EGMax8YYRGEV3Hv7PW5iCWH1KkTxY=",
		},
		{
			name:     "SASLprep maps the non-breaking space to a space",
			password: "pass\u00A0word",
			expected: "SCRAM-SHA-256$4096:JCLRdknnFitMS7xv5++m2Q==$X6KB8r9pRJD6uW+SYgshLFKm9++MIq921DNE4rX+cc4=:mU0EQY/2zqRuKqOjGDcU5yeFIkKXW+KfiCt4rbA0tz0=",
		},
		{
			name:     "SASLprep normalizes with NFKC",
			password: "\u2168\uFB01sh",
			expected: "SCRAM-SHA-256$4096:C46PBn/WkDc8GK9Hzc9bOQ==$4ku5fZtCm30dlZuUAIm+pKO5J3+slPJDv4puX3YloMs=:YfJmyyjftlt14ZCkgvv/Tisl9NfaFfEL24sXj/T4kKE=",
		},
		{
			name:     "ASCII control character is kept as-is",
			password: "pass\u0007word",
			expected: "SCRAM-SHA-256$4096:7bgFF4SLnLTpYvsxsnTjFQ==$/pVwcFgvzbx6o4Jd8gcFG59vxAAvp9qoxKmPi6t1eRE=:J5wobfpza7LIExS/J1CFIQ/ixm6H5JM20ykbZPjZLiQ=",
		},
		{
			name:     "character prohibited by SASLprep is kept as-is",
			password: "pass\uE000word",
			expected: "SCRAM-SHA-256$4096:USZpKv6X6mw2JnuaqvPmiA==$GZmwhzoOd6crGdDX5fiTAaO2zUEEkYoxmfOp1w+lvSs=:GA0hqb1o5lzOHT4nDs22B+i234m3u28ePXSCFag/cQ0=",
		},
		{
			name:     "bidirectional string prohibited by SASLprep is kept as-is",
			password: "\u05D0abc",
			expected: "SCRAM-SHA-256$4096:ylTYggKWmWbq607V6FryHg==$wVJfgzEDJfftLpP+F7k9ZL0jX4hFZ4Kg+MDWjUIFTwg=:eKf6tHIDnm5c4NP8nBvChEyxmSknSjL7SD61q7pKf0o=",
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			// SCRAM-SHA-256$<iterations>:<salt>$<StoredKey>:<ServerKey>
			parameters := strings.Split(strings.Split(test.expected, "$")[1], ":")
			iterations, err := strconv.Atoi(parameters[0])
			require.NoError(t, err)
			salt, err := base64.StdEncoding.DecodeString(parameters[1])
			require.NoError(t, err)

			actual, err := scramSHA256Password(test.password, salt, iterations)

			require.NoError(t, err)
			assert.Equal(t, test.expected, actual)
			assert.True(t, isHashedPassword(actual))
		})
	}
}

func TestNewScramSHA256Salt(t *testing.T) {
	first, err := newScramSHA256Salt()
	require.NoError(t, err)
	second, err := newScramSHA256Salt()
	require.NoError(t, err)

	assert.Len(t, first, scramSHA256SaltLength)
	assert.NotEqual(t, first, second)
}

func TestIsHashedPassword(t *testing.T) {
	var tests = []struct {
		password string
		expected bool
	}{
		{"md5c98cbfeb6a347a47eb8e96cfb4c4b890", true},
		{"SCRAM-SHA-256$4096:nBZw/pXHfglx9Uj38kTBaw==$kGNAwejTyDeIo7PF3ThjzBaKwu6Dw5If2OYxTD2AstI=:U/rTZUu3HZekCvxnzF65xDuso9CTdPudq8r2EvaCHao=", true},
		{"", false},
		{"mypass", false},
		// PostgreSQL only recognizes "md5" followed by 32 lowercase hexadecimal digits
		{"md5", false},
		{"md5pass", false},
		{"md5C98CBFEB6A347A47EB8E96CFB4C4B890", false},
		{"md5c98cbfeb6a347a47eb8e96cfb4c4b890a", false},
		// A clear-text password which only looks like a SCRAM-SHA-256 one
		{"SCRAM-SHA-256", false},
		{"SCRAM-SHA-256$mypass", false},
		{"SCRAM-SHA-256$4096:salt", false},
	}

	for _, test := range tests {
		t.Run(test.password, func(t *testing.T) {
			assert.Equal(t, test.expected, isHashedPassword(test.password))
		})
	}
}
